import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"PIGLIN KING プロローグ 黄金王のいない時代","description":"","frontmatter":{"title":"PIGLIN KING プロローグ 黄金王のいない時代","outline":"deep"},"headers":[],"relativePath":"story/prologue.md","filePath":"story/prologue.md"}'),o={name:"story/prologue.md"};function i(l,p,h,n,s,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="プロローグ-黄金王のいない時代" tabindex="-1">プロローグ 黄金王のいない時代 <a class="header-anchor" href="#プロローグ-黄金王のいない時代" aria-label="Permalink to &quot;プロローグ 黄金王のいない時代&quot;">​</a></h2><hr><h1 id="黄金王のいない時代" tabindex="-1">黄金王のいない時代 <a class="header-anchor" href="#黄金王のいない時代" aria-label="Permalink to &quot;黄金王のいない時代&quot;">​</a></h1><p>昔々。</p><p>まだ、</p><p>PIGLIN KINGDOMという国が存在しなかった頃。</p><p>世界は混乱に満ちていた。</p><p>ネザーには無数の部族が存在し、</p><p>互いに争い、</p><p>奪い合い、</p><p>信じるものもなく生きていた。</p><p>ある者は力を求め。</p><p>ある者は富を求め。</p><p>ある者はただ生き延びるために戦った。</p><p>誰も、</p><p>未来を信じていなかった。</p><p>誰も、</p><p>平和など夢物語だと思っていた。</p><p>そして、</p><p>誰も知らなかった。</p><p>後に「黄金王」と呼ばれる、</p><p>一人の若いピグリンが、</p><p>どこかで普通に暮らしていることを。</p><hr><h1 id="一人の若者" tabindex="-1">一人の若者 <a class="header-anchor" href="#一人の若者" aria-label="Permalink to &quot;一人の若者&quot;">​</a></h1><p>その若者の名は、</p><p>Aurex Goldtusk。</p><p>オーレックス・ゴールドタスク。</p><p>後の、</p><p>KING PIGLIN I。</p><p>しかし。</p><p>この頃の彼は、</p><p>まだ王ではなかった。</p><p>英雄でもなかった。</p><p>ただの若いピグリンだった。</p><p>宝物を集めることが好きで、</p><p>甘いものが好きで、</p><p>少しお人好しで、</p><p>困っている人を放っておけない。</p><p>そんな、</p><p>どこにでもいる普通の若者。</p><p>彼自身も、</p><p>自分が王になるとは思っていなかった。</p><p>世界を救うことになるとも、</p><p>思っていなかった。</p><p>ただ、</p><p>笑って暮らせる毎日を願っていただけだった。</p><hr><h1 id="二人の出会い" tabindex="-1">二人の出会い <a class="header-anchor" href="#二人の出会い" aria-label="Permalink to &quot;二人の出会い&quot;">​</a></h1><p>そして。</p><p>運命は、</p><p>静かに動き始める。</p><p>一人目。</p><p>豪快で、</p><p>少し騒がしくて、</p><p>誰よりも仲間思いな戦士。</p><p>後に英雄と呼ばれる男。</p><p>スターリン。</p><p>二人目。</p><p>冷静で、</p><p>頭が良く、</p><p>少し皮肉屋だが、</p><p>誰よりも優しい学者。</p><p>ピックバーグ。</p><p>まだ。</p><p>三人は知らない。</p><p>共に笑い。</p><p>共に泣き。</p><p>共に旅をし。</p><p>共に世界を救うことになることを。</p><p>そして。</p><p>最後の時まで、</p><p>親友であり続けることを。</p><hr><h1 id="黄金の冠" tabindex="-1">黄金の冠 <a class="header-anchor" href="#黄金の冠" aria-label="Permalink to &quot;黄金の冠&quot;">​</a></h1><p>その頃。</p><p>世界のどこか。</p><p>忘れ去られた砦の奥深く。</p><p>一つの冠が、</p><p>長い眠りについていた。</p><p>黄金の冠。</p><p>古代より受け継がれる王の証。</p><p>それは、</p><p>力を求める者を拒み。</p><p>民を愛する者を選ぶ。</p><p>誰も知らない。</p><p>その冠が、</p><p>一人の若者を待ち続けていることを。</p><p>誰も知らない。</p><p>その冠が、</p><p>世界の運命を変えることを。</p><hr><h1 id="まだ始まっていない物語" tabindex="-1">まだ始まっていない物語 <a class="header-anchor" href="#まだ始まっていない物語" aria-label="Permalink to &quot;まだ始まっていない物語&quot;">​</a></h1><p>王国はまだない。</p><p>英雄もまだいない。</p><p>伝説もまだない。</p><p>あるのは、</p><p>三人の若者たちと、</p><p>果てしなく広い世界だけ。</p><p>だが。</p><p>やがて彼らは出会う。</p><p>旅に出る。</p><p>戦う。</p><p>笑う。</p><p>泣く。</p><p>愛する人を見つける。</p><p>家族を作る。</p><p>そして。</p><p>国を築く。</p><p>それは、</p><p>戦いの物語であり。</p><p>冒険の物語であり。</p><p>友情の物語であり。</p><p>愛の物語。</p><p>そして。</p><p>一人の優しい王の、</p><p>生涯の物語。</p><hr><p>ページをめくろう。</p><p>物語は、</p><p>まだ始まったばかり。</p><hr><p>PIGLIN KING</p><p>プロローグ　黄金王のいない時代</p>',125)])])}const I=a(o,[["render",i]]);export{u as __pageData,I as default};
